package server

// Source-owned additions to the historical spreadsheet catalog. Keep these
// outside its generated file so rebuilding that file cannot erase live codes.
// When a code enters the spreadsheet, remove its extension in the same change.
func init() {
	for _, entry := range []CatalogEntry{
		// Stage 49.4.4 shared request envelope (internal/server/request_envelope.go).
		// Client errors with no business content, so none is logged: an attacker
		// probing the limits must not be able to flood system_error_logs.
		{Code: "GLOBAL-0303", MessageID: "EXT-GLOBAL-0303", Module: "Global", Scenario: "Request method not allowed", MessageType: "Error", UserMessage: "This request method is not supported here.", UserAction: "Use GET to read and POST, PUT or DELETE to change data, as the API documentation shows.", Severity: "Low", Blocking: true, DisplayStyle: "Toast", HTTPStatus: 405, Priority: "P3", RequirementLevel: "Mature ERP"},
		{Code: "GLOBAL-0304", MessageID: "EXT-GLOBAL-0304", Module: "Global", Scenario: "Request content type or encoding not accepted", MessageType: "Error", UserMessage: "The request body is in a format this address does not accept.", UserAction: "Send JSON (Content-Type: application/json), or a file upload as multipart/form-data, without compression.", Severity: "Low", Blocking: true, DisplayStyle: "Toast", HTTPStatus: 415, Priority: "P3", RequirementLevel: "Mature ERP"},
		{Code: "GLOBAL-0305", MessageID: "EXT-GLOBAL-0305", Module: "Global", Scenario: "Request body too large", MessageType: "Error", UserMessage: "The request is too large to accept.", UserAction: "Send less data at once - split a large file or list into smaller parts.", Severity: "Low", Blocking: true, DisplayStyle: "Page banner", HTTPStatus: 413, Priority: "P3", RequirementLevel: "Mature ERP"},
		{Code: "GLOBAL-0306", MessageID: "EXT-GLOBAL-0306", Module: "Global", Scenario: "Request headers too large", MessageType: "Error", UserMessage: "The request carries too many or too large headers.", UserAction: "Sign out and back in; if this persists, contact support - a browser extension or proxy may be adding headers.", Severity: "Low", Blocking: true, DisplayStyle: "Toast", HTTPStatus: 431, Priority: "P3", RequirementLevel: "Mature ERP"},
		{Code: "GLOBAL-0307", MessageID: "EXT-GLOBAL-0307", Module: "Global", Scenario: "Malformed, ambiguous or over-nested JSON request", MessageType: "Error", UserMessage: "The request data could not be accepted.", UserAction: "Check the request is one valid JSON value, with no field repeated in the same object.", Severity: "Low", Blocking: true, DisplayStyle: "Toast", HTTPStatus: 400, Priority: "P3", RequirementLevel: "Mature ERP"},
		{Code: "GLOBAL-0308", MessageID: "EXT-GLOBAL-0308", Module: "Global", Scenario: "Request exceeded its time limit", MessageType: "Error", UserMessage: "This took longer than the time a single request is allowed, so it was stopped.", UserAction: "Send less at once - split a large import file into smaller files, or narrow a report's filters and use background export.", Severity: "Medium", Blocking: true, DisplayStyle: "Page banner", HTTPStatus: 504, LogRequired: true, Priority: "P2", RequirementLevel: "Mature ERP"},
		{Code: "GOODSR-0096", MessageID: "EXT-GOODSR-0096", Module: "Goods Receipt", Scenario: "Damaged quantity requires a reason", MessageType: "Error", UserMessage: "Enter a damage reason for each damaged receipt line.", UserAction: "Record the observed damage and submit the receipt again.", Severity: "High", Blocking: true, DisplayStyle: "Field inline", HTTPStatus: 422, LogRequired: true, Priority: "P1", RequirementLevel: "Mature ERP"},
		{Code: "GOODSR-0097", MessageID: "EXT-GOODSR-0097", Module: "Goods Receipt", Scenario: "Rejected and damaged quantities exceed received quantity", MessageType: "Error", UserMessage: "Rejected plus damaged quantity cannot exceed received quantity.", UserAction: "Check the received, rejected and damaged counts; correct the line before submitting.", Severity: "High", Blocking: true, DisplayStyle: "Field inline", HTTPStatus: 422, LogRequired: true, Priority: "P1", RequirementLevel: "Mature ERP"},
		{Code: "DATAIM-0189", MessageID: "EXT-DATAIM-0189", Module: "Data Import / Excel Upload", Scenario: "Uploaded file exceeds the maximum import row count", MessageType: "Error", UserMessage: "This file has too many rows to import in one go.", UserAction: "Split the file into smaller batches and import them one at a time.", Severity: "Medium", Blocking: true, DisplayStyle: "Page banner", HTTPStatus: 422, LogRequired: true, Priority: "P2", RequirementLevel: "Mature ERP"},
		{Code: "ASSET-0273", MessageID: "EXT-ASSET-0273", Module: "Fixed Assets", Scenario: "A Fixed Asset item was put on a sale, order or invoice", MessageType: "Error", UserMessage: "This item is a fixed asset, not stock for sale, so it cannot be sold, ordered or invoiced.", UserAction: "Remove it from the sale. Fixed assets are managed under HRM -> Fixed Assets.", Severity: "High", Blocking: true, DisplayStyle: "Page banner", HTTPStatus: 422, LogRequired: true, Priority: "P1", RequirementLevel: "Mature ERP"},
		{Code: "POSOFF-0245", MessageID: "EXT-POSOFF-0245", Module: "POS / Billing", Scenario: "POS session or sale attempted at a location that is not a selling location", MessageType: "Error", UserMessage: "This location is not a selling location, so a till cannot sell from it.", UserAction: "Choose the store you are selling from, or ask an administrator to set Sellable = Yes on this Location.", Severity: "High", Blocking: true, DisplayStyle: "Page banner", HTTPStatus: 422, LogRequired: true, Priority: "P1", RequirementLevel: "Mature ERP"},
	} {
		if _, exists := errorCatalog[entry.Code]; exists {
			panic("duplicate error catalog extension: " + entry.Code)
		}
		errorCatalog[entry.Code] = entry
	}
}
